# Generated by build.py from recipe.yml for recipe http-accept-uploads. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'drop' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'notes.txt'), "uploaded by curl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'drop/readme.txt'), "read me`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-uploads', '--user', 'alice:s3cret', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --digest -u alice:s3cret -T notes.txt http://127.0.0.1:8080/notes.txt } finally { Stop-Process $server0 }
